from typing import Tuple

class Posicao(object):
    """Representa uma posição geográfica composta por latitude e longitude."""

    def __init__(self, latitude: float = None, longitude: float = None):
        self.latitude = latitude
        self.longitude = longitude

    @property
    def coordinates_tuple(self) -> Tuple[float, float]:
        """Retorna as coordenadas como tupla (latitude, longitude)."""
        return self.latitude, self.longitude

    @coordinates_tuple.setter
    def coordinates_tuple(self, coords: Tuple[float, float]):
        """Define as coordenadas a partir de uma tupla (latitude, longitude)."""
        self.latitude, self.longitude = coords

class PontoGeografico(object):
    """Encapsula uma posição geográfica específica."""

    def __init__(self, position: Posicao = None):
        self.position = position or Posicao()  

class Onde(object):
    """Contém um ou vários pontos geográficos."""

    def __init__(self, points: list[PontoGeografico]=None):
        self.points = points or []

class Localizacao(object):

    def __init__(self, where_element: Onde = None):
        self.where_element = where_element or Onde()

    def append_point(self, latitude: float, longitude: float):
        """Adiciona um novo ponto geográfico."""
        position = Posicao(latitude, longitude)
        point = PontoGeografico(position)
        self.where_element.points.append(point)

    def remove_last_point(self):
        """Remove o último ponto adicionado."""
        if len(self.where_element.points)>0:
            del self.where_element.points[-1]

    def last_coordinates_added(self)->Tuple[float,float]:
        """Obtem as últimas coordenadas adicionadas."""
        if len(self.where_element.points)==0:
          raise ValueError("Não há nenhum ponto registrado.")

        return self.where_element.points[-1].position.coordinates_tuple

